from common import *
import io
m=load(); s=scp()
out=io.StringIO()
def P(*a): print(*a,file=out)
P("# Paper 02 — first-pass results (public data only)\n")
P("Generated by `p02.py` on 2026-11-26. Sources: State Cancer Profiles (NPCR; incidence 2019-2023, mortality 2020-2024; county rural/urban from 2023 USDA RUCC), CDC PLACES 2025 release (BRFSS 2023), County Health Rankings supplemental release (Mar 2026). All values are published aggregates; no counts <11 are reported.\n")
# A state level race
P("## A. Mississippi state-level, by race/ethnicity (SCP)\n")
rows=[]
for lab,ds in [('Black NH','blackNH'),('White NH','whiteNH')]:
    i=state_row('oral_inc_'+ds); mo=state_row('oral_mort_'+ds); l=state_row('oral_late_'+ds)
    rows.append([lab,i.rate_per_100k,f"{i.ci_lo}-{i.ci_hi}",mo.rate_per_100k,f"{mo.ci_lo}-{mo.ci_hi}",l.pct_late,l.avg_annual_count])
t=pd.DataFrame(rows,columns=['Group','Incidence/100k','95% CI','Mortality/100k','95% CI ','% late stage','Late-stage avg annual count'])
P(t.to_markdown(index=False)); P()
b=state_row('oral_inc_blackNH'); w=state_row('oral_inc_whiteNH'); bm=state_row('oral_mort_blackNH'); wm=state_row('oral_mort_whiteNH')
e=rr(b.rate_per_100k,b.ci_lo,b.ci_hi,w.rate_per_100k,w.ci_lo,w.ci_hi)
P(f"- Incidence rate ratio Black NH / White NH = {e[0]:.2f} (approx 95% CI {e[1]:.2f}-{e[2]:.2f}; CI derived from published rate CIs, log-normal approximation).")
e2=rr(bm.rate_per_100k,bm.ci_lo,bm.ci_hi,wm.rate_per_100k,wm.ci_lo,wm.ci_hi)
P(f"- Mortality rate ratio Black NH / White NH = {e2[0]:.2f} (approx 95% CI {e2[1]:.2f}-{e2[2]:.2f}).")
P(f"- Mortality-to-incidence ratio of age-adjusted rates (mort 2020-24 / inc 2019-23; descriptive, periods differ): Black NH {bm.rate_per_100k/b.rate_per_100k:.2f}, White NH {wm.rate_per_100k/w.rate_per_100k:.2f}.")
# late stage test: approximate counts from published avg annual counts x5
bl=state_row('oral_late_blackNH'); wl=state_row('oral_late_whiteNH')
nb=b.avg_annual_count*5; nw=w.avg_annual_count*5
xb=round(bl.avg_annual_count*5); xw=round(wl.avg_annual_count*5)
tab=np.array([[xb,nb-xb],[xw,nw-xw]])
chi=stats.chi2_contingency(tab,correction=False)
P(f"- Late-stage share: Black NH {bl.pct_late}% vs White NH {wl.pct_late}% (published). Approximate chi-square on counts reconstructed from published average annual counts x5 (rounded, so approximate): late/total Black ~{xb}/{int(nb)}, White ~{xw}/{int(nw)}; chi2={chi[0]:.2f}, p={'<0.001' if chi[1]<0.001 else format(chi[1],'.3f')}.")
for lab,ds in [('Male Black NH','oral_inc_blackNH_male'),('Male White NH','oral_inc_whiteNH_male'),('Male all','oral_inc_male'),('Female all','oral_inc_female')]:
    r=state_row(ds); P(f"- {lab} incidence: {r.rate_per_100k} ({r.ci_lo}-{r.ci_hi}) per 100k")
for lab,ds in [('Male Black NH','oral_mort_blackNH_male'),('Male White NH','oral_mort_whiteNH_male')]:
    r=state_row(ds); P(f"- {lab} mortality: {r.rate_per_100k} ({r.ci_lo}-{r.ci_hi}) per 100k")
a=state_row('oral_inc_all'); au=state_row('oral_inc_all',fips='00000'); ma=state_row('oral_mort_all'); mu=state_row('oral_mort_all',fips='00000')
P(f"- MS vs US all-race incidence: {a.rate_per_100k} ({a.ci_lo}-{a.ci_hi}) vs {au.rate_per_100k} ({au.ci_lo}-{au.ci_hi}); mortality {ma.rate_per_100k} ({ma.ci_lo}-{ma.ci_hi}) vs {mu.rate_per_100k} ({mu.ci_lo}-{mu.ci_hi}); late-stage share {state_row('oral_late_all').pct_late}% vs {state_row('oral_late_all',fips='00000').pct_late}%.")
P()
bmm=state_row('oral_mort_blackNH_male'); wmm=state_row('oral_mort_whiteNH_male'); bim=state_row('oral_inc_blackNH_male'); wim=state_row('oral_inc_whiteNH_male')
P(f"- Male mortality-to-incidence ratio: Black NH {bmm.rate_per_100k/bim.rate_per_100k:.2f}, White NH {wmm.rate_per_100k/wim.rate_per_100k:.2f}.")
# B county
P("## B. County level (82 counties): availability and rural/urban\n")
inc=county_scp('oral_inc_all'); inc=inc[['fips','county','scp_rural_urban','rate_per_100k','ci_lo','ci_hi','avg_annual_count']].rename(columns={'rate_per_100k':'oral_inc','ci_lo':'oral_inc_lo','ci_hi':'oral_inc_hi','avg_annual_count':'oral_inc_avgcount'})
mo=county_scp('oral_mort_all')[['fips','rate_per_100k','avg_annual_count']].rename(columns={'rate_per_100k':'oral_mort','avg_annual_count':'oral_mort_avgcount'})
la=county_scp('oral_late_all')[['fips','pct_late','rate_per_100k']].rename(columns={'rate_per_100k':'oral_late_rate'})
mi=county_scp('oral_inc_male')[['fips','rate_per_100k']].rename(columns={'rate_per_100k':'oral_inc_male'})
wi=county_scp('oral_inc_whiteNH')[['fips','rate_per_100k']].rename(columns={'rate_per_100k':'oral_inc_whiteNH'})
bi=county_scp('oral_inc_blackNH')[['fips','rate_per_100k']].rename(columns={'rate_per_100k':'oral_inc_blackNH'})
lu=county_scp('lung_inc_all')[['fips','rate_per_100k']].rename(columns={'rate_per_100k':'lung_inc'})
d=m.merge(inc.drop(columns='county'),on='fips',how='left')
for x in [mo,la,mi,wi,bi,lu]: d=d.merge(x,on='fips',how='left')
d.to_csv('results/p02/p02_county_dataset.csv',index=False)
P(f"- Counties with a published (non-suppressed) all-race incidence rate: {d.oral_inc.notna().sum()}/82. Suppressed: {d.oral_inc.isna().sum()} (SCP suppresses area-race-sex cells with <16 cases in 5 years).")
P(f"- Counties with published mortality rate: {d.oral_mort.notna().sum()}; late-stage rate: {d.oral_late_rate.notna().sum()}; White NH incidence: {d.oral_inc_whiteNH.notna().sum()}; Black NH incidence: {d.oral_inc_blackNH.notna().sum()}.")
P("- County-level Black/White comparisons and mortality are too sparse for county analysis (see counts above); these stay state-level. County analyses use all-race incidence only.\n")
P("**Selection caveat**: suppression removes mostly small rural counties, so rural-vs-urban comparisons among non-suppressed counties are biased toward larger rural counties.\n")
dd=d[d.oral_inc.notna()].copy()
dd['group']=np.where(dd.nonmetro==1,'Nonmetro (RUCC 4-9)','Metro (RUCC 1-3)')
g=dd.groupby('group').agg(n=('oral_inc','size'),median=('oral_inc','median'),mean=('oral_inc','mean'),iqr_lo=('oral_inc',lambda x:x.quantile(.25)),iqr_hi=('oral_inc',lambda x:x.quantile(.75)))
P("### Oral cavity & pharynx incidence per 100k by metro status (non-suppressed counties)\n"); P(g.round(1).to_markdown()); P()
a1=dd[dd.nonmetro==1].oral_inc; a0=dd[dd.nonmetro==0].oral_inc
u=stats.mannwhitneyu(a1,a0); P(f"- Mann-Whitney nonmetro vs metro: U={u.statistic:.0f}, p={u.pvalue:.3f}")
# weighted by avg annual count
dd2=dd.dropna(subset=['oral_inc_avgcount'])
mod=sm.WLS(dd2.oral_inc,sm.add_constant(dd2[['nonmetro']]),weights=dd2.oral_inc_avgcount).fit(cov_type='HC3')
P(f"- WLS (weights=avg annual count) nonmetro coefficient: {mod.params['nonmetro']:.2f} per 100k (95% CI {mod.conf_int().loc['nonmetro',0]:.2f} to {mod.conf_int().loc['nonmetro',1]:.2f}), p={mod.pvalues['nonmetro']:.3f}, n={len(dd2)}")
dr=dd.groupby('dra_county').oral_inc.agg(['size','median']).round(1); P(f"- By DRA(Delta region) county: {dr.to_dict('index')}")
u2=stats.mannwhitneyu(dd[dd.dra_county==1].oral_inc,dd[dd.dra_county==0].oral_inc); P(f"- Mann-Whitney DRA vs non-DRA: p={u2.pvalue:.3f}\n")
P("### Spearman correlations with county oral cavity & pharynx incidence (non-suppressed counties)\n")
rows=[]
for v,lab in [('pl_csmoking','Current smoking, % (PLACES 2023)'),('pl_binge','Binge drinking, % (PLACES 2023)'),('pl_teethlost','All teeth lost, age>=65, % (PLACES 2022)'),
              ('pl_access2_uninsured','Uninsured 18-64, % (PLACES 2023)'),('pcp_per100k','PCP per 100k (CHR 2025 supp)'),('dentist_per100k','Dentists per 100k (CHR)'),('child_poverty','Children in poverty, %'),('pct_black_nh','% Black NH'),('pct_rural_chr','% rural'),('lung_inc','Lung cancer incidence (SCP)')]:
    n,r,p=spearman(d[v],d.oral_inc); rows.append([lab,n,r,p])
P(pd.DataFrame(rows,columns=['Variable','n counties','Spearman rho','p']).to_markdown(index=False,floatfmt='.3f')); P()
P("### Multivariable (OLS, HC3 robust SE), outcome = oral cavity & pharynx incidence per 100k\n")
mod,t,n=ols(d,'oral_inc',['pl_csmoking','nonmetro','pcp_per100k','child_poverty'])
P(f"n={n} counties; R2={mod.rsquared:.2f}\n"); P(t.round(3).to_markdown()); P("\n(Ecological, exploratory; non-suppressed counties only.)\n")
# late stage
P("### County % late stage (all race) vs covariates\n")
rows=[]
for v,lab in [('nonmetro','Nonmetro (0/1)'),('pcp_per100k','PCP per 100k'),('pl_access2_uninsured','Uninsured 18-64, %'),('pl_csmoking','Smoking, %'),('child_poverty','Child poverty, %')]:
    n,r,p=spearman(d[v],d.pct_late); rows.append([lab,n,r,p])
P(pd.DataFrame(rows,columns=['Variable','n counties with % late','Spearman rho','p']).to_markdown(index=False,floatfmt='.3f')); P()
open('results/p02/p02_results.md','w').write(out.getvalue()); print(out.getvalue())
